const students = [
  { name: 'สมชาย ใจดี', grade: 'ม.1/1' },
  { name: 'สมหญิง รักเรียน', grade: 'ม.1/1' },
  { name: 'วิชัย ตั้งใจ', grade: 'ม.1/2' },
  { name: 'มานี มีนา', grade: 'ม.1/2' },
  { name: 'ปิติ ยินดี', grade: 'ม.1/3' },
  { name: 'ชูใจ ใจงาม', grade: 'ม.1/3' },
  { name: 'ดวงใจ สว่างไสว', grade: 'ม.1/4' },
  { name: 'เอกชัย แข็งแรง', grade: 'ม.1/4' },
  { name: 'พรทิพย์ โชคดี', grade: 'ม.1/1' },
  { name: 'สุดา ขยันเรียน', grade: 'ม.1/2' },
  { name: 'อนันต์ พากเพียร', grade: 'ม.1/3' },
  { name: 'กมลชนก แสนดี', grade: 'ม.1/4' }
];

// คำถามทั้ง 10 ข้อ พร้อมตัวเลือกทั้งหมดและ index ของคำตอบที่ถูกต้อง (อ้างอิงจาก n8n Form Trigger)
const QUESTIONS = [
  { options: ['เซลล์ (Cell)', 'อะตอม (Atom)', 'เนื้อเยื่อ (Tissue)', 'อวัยวะ (Organ)'], correctIndex: 0 },
  { options: ['ไนโตรเจน (N2)', 'ออกซิเจน (O2)', 'ไฮโดรเจน (H2)', 'คาร์บอนไดออกไซด์ (CO2)'], correctIndex: 3 },
  { options: ['100 องศาเซลเซียส', '0 องศาเซลเซียส', '50 องศาเซลเซียส', '37 องศาเซลเซียส'], correctIndex: 0 },
  { options: ['นิวเคลียส (Nucleus)', 'คลอโรพลาสต์ (Chloroplast)', 'ไมโทคอนเดรีย (Mitochondria)', 'ไรโบโซม (Ribosome)'], correctIndex: 2 },
  { options: ['แวคิวโอล (Vacuole)', 'ผนังเซลล์ (Cell Wall)', 'เยื่อหุ้มเซลล์ (Cell Membrane)', 'นิวเคลียส (Nucleus)'], correctIndex: 3 },
  { options: ['ผนังเซลล์ (Cell Wall)', 'เยื่อหุ้มเซลล์ (Cell Membrane)', 'นิวเคลียส (Nucleus)', 'ไมโทคอนเดรีย (Mitochondria)'], correctIndex: 0 },
  { options: ['การสังเคราะห์ด้วยแสง (Photosynthesis)', 'การหายใจ (Respiration)', 'การคายน้ำ (Transpiration)', 'การย่อยอาหาร (Digestion)'], correctIndex: 0 },
  { options: ['สิ่งมีชีวิตหลายเซลล์ (Multicellular)', 'อวัยวะ (Organ)', 'สิ่งมีชีวิตเซลล์เดียว (Unicellular)', 'เนื้อเยื่อ (Tissue)'], correctIndex: 2 },
  { options: ['ระบบอวัยวะ → อวัยวะ → เซลล์ → เนื้อเยื่อ', 'เซลล์ → เนื้อเยื่อ → อวัยวะ → ระบบอวัยวะ', 'อวัยวะ → เนื้อเยื่อ → เซลล์ → ระบบอวัยวะ', 'เนื้อเยื่อ → เซลล์ → อวัยวะ → ระบบอวัยวะ'], correctIndex: 1 },
  { options: ['สร้างอาหารให้เซลล์โดยตรง', 'กำจัดของเสียออกจากเซลล์', 'สร้างพลังงาน (ATP) ให้เซลล์นำไปใช้งาน', 'ควบคุมการแบ่งตัวของเซลล์'], correctIndex: 2 }
];

const results = [];

for (const student of students) {
  const answers = [];
  const isCorrect = [];
  let correctCount = 0;

  for (const q of QUESTIONS) {
    // ~70% โอกาสตอบถูกในแต่ละข้อ เพื่อให้คะแนนกระจายตัวสมจริง
    const answerCorrect = Math.random() < 0.7;
    const wrongIndexes = q.options.map((_, i) => i).filter((i) => i !== q.correctIndex);
    const chosenIndex = answerCorrect
      ? q.correctIndex
      : wrongIndexes[Math.floor(Math.random() * wrongIndexes.length)];

    answers.push(q.options[chosenIndex]);
    const correct = chosenIndex === q.correctIndex;
    isCorrect.push(correct);
    if (correct) correctCount++;
  }

  const score = correctCount;
  const totalScore = 10;
  const percentage = Math.round((score / totalScore) * 100 * 10) / 10;
  const passStatus = percentage >= 50 ? 'ผ่าน' : 'ไม่ผ่าน';

  // สุ่มเวลาส่งย้อนหลังภายใน 7 วัน ให้ข้อมูลดูสมจริง
  const submittedDate = new Date();
  submittedDate.setDate(submittedDate.getDate() - Math.floor(Math.random() * 7));
  submittedDate.setHours(submittedDate.getHours() - Math.floor(Math.random() * 24));

  results.push({
    json: {
      student_name: student.name,
      grade_level: student.grade,
      subject: 'วิทยาศาสตร์',
      test_name: 'แบบทดสอบบทที่ 1: หน่วยของสิ่งมีชีวิต',
      score: score,
      total_score: totalScore,
      percentage: percentage,
      pass_status: passStatus,
      answer_1: answers[0],
      answer_2: answers[1],
      answer_3: answers[2],
      answer_4: answers[3],
      answer_5: answers[4],
      answer_6: answers[5],
      answer_7: answers[6],
      answer_8: answers[7],
      answer_9: answers[8],
      answer_10: answers[9],
      is_correct_1: isCorrect[0],
      is_correct_2: isCorrect[1],
      is_correct_3: isCorrect[2],
      is_correct_4: isCorrect[3],
      is_correct_5: isCorrect[4],
      is_correct_6: isCorrect[5],
      is_correct_7: isCorrect[6],
      is_correct_8: isCorrect[7],
      is_correct_9: isCorrect[8],
      is_correct_10: isCorrect[9],
      submitted_at: submittedDate.toLocaleString('th-TH')
    }
  });
}

return results;

const items = $input.all();
const results = [];

// นิยามคำถามทั้ง 10 ข้อ + เงื่อนไขคำตอบที่ถูกต้อง (ใช้ .includes เพื่อให้ทนต่อการเปลี่ยน label เล็กน้อย)
const QUESTIONS = [
  { key: "ข้อ 1: ข้อใดคือหน่วยพื้นฐานที่เล็กที่สุดของสิ่งมีชีวิต?", correctMatch: "เซลล์" },
  { key: "ข้อ 2: พืชใช้ก๊าซใดเป็นวัตถุดิบหลักในกระบวนการสังเคราะห์ด้วยแสง?", correctMatch: "คาร์บอนไดออกไซด์" },
  { key: "ข้อ 3: อุณหภูมิจุดเดือดของน้ำบริสุทธิ์ที่ระดับน้ำทะเลคือเท่าใด?", correctMatch: "100" },
  { key: "ข้อ 4: ออร์แกเนลล์ใดทำหน้าที่สร้างพลังงานให้แก่เซลล์ (Powerhouse of the Cell)?", correctMatch: "ไมโทคอนเดรีย" },
  { key: "ข้อ 5: ส่วนใดของเซลล์ทำหน้าที่ควบคุมกิจกรรมต่าง ๆ เปรียบเสมือนสมองของเซลล์?", correctMatch: "นิวเคลียส" },
  { key: "ข้อ 6: โครงสร้างใดพบเฉพาะในเซลล์พืช แต่ไม่พบในเซลล์สัตว์?", correctMatch: "ผนังเซลล์" },
  { key: "ข้อ 7: กระบวนการที่พืชสร้างอาหารเองได้โดยใช้แสงแดด เรียกว่าอะไร?", correctMatch: "สังเคราะห์ด้วยแสง" },
  { key: "ข้อ 8: สิ่งมีชีวิตที่มีร่างกายประกอบด้วยเซลล์เพียงเซลล์เดียวเรียกว่าอะไร?", correctMatch: "เซลล์เดียว" },
  { key: "ข้อ 9: ระดับการจัดระเบียบของสิ่งมีชีวิตข้อใดเรียงลำดับจากเล็กไปใหญ่ได้ถูกต้อง?", correctMatch: "เซลล์ → เนื้อเยื่อ" },
  { key: "ข้อ 10: กระบวนการหายใจระดับเซลล์ (Cellular Respiration) มีหน้าที่อะไร?", correctMatch: "ATP" }
];

for (const item of items) {
  const data = item.json;

  const studentName = data['ชื่อ-นามสกุล นักเรียน'] || 'ไม่ระบุชื่อ';
  const gradeLevel = data['ระดับชั้น / ห้องเรียน'] || 'ม.1/1';

  // เก็บคำตอบดิบของแต่ละข้อ + เช็คถูก/ผิดเป็นรายข้อ เพื่อบันทึกลง Data Table
  const answers = QUESTIONS.map((q) => data[q.key] || '');
  const isCorrect = QUESTIONS.map((q, i) => answers[i].includes(q.correctMatch));
  const correctCount = isCorrect.filter(Boolean).length;

  // ข้อสอบ 10 ข้อ ข้อละ 1 คะแนน คะแนนเต็ม 10
  const score = correctCount;
  const totalScore = 10;
  const percentage = Math.round((score / totalScore) * 100 * 10) / 10;
  const passStatus = percentage >= 50 ? 'ผ่าน' : 'ไม่ผ่าน';
  const now = new Date();

  results.push({
    json: {
      student_name: studentName,
      grade_level: gradeLevel,
      subject: 'วิทยาศาสตร์',
      test_name: 'แบบทดสอบบทที่ 1: หน่วยของสิ่งมีชีวิต',
      score: score,
      total_score: totalScore,
      percentage: percentage,
      pass_status: passStatus,
      correct_count: correctCount,
      total_questions: 10,
      // คำตอบรายข้อ + ถูก/ผิดรายข้อ (ข้อ 1-10)
      answer_1: answers[0],
      answer_2: answers[1],
      answer_3: answers[2],
      answer_4: answers[3],
      answer_5: answers[4],
      answer_6: answers[5],
      answer_7: answers[6],
      answer_8: answers[7],
      answer_9: answers[8],
      answer_10: answers[9],
      is_correct_1: isCorrect[0],
      is_correct_2: isCorrect[1],
      is_correct_3: isCorrect[2],
      is_correct_4: isCorrect[3],
      is_correct_5: isCorrect[4],
      is_correct_6: isCorrect[5],
      is_correct_7: isCorrect[6],
      is_correct_8: isCorrect[7],
      is_correct_9: isCorrect[8],
      is_correct_10: isCorrect[9],
      submitted_at: now.toLocaleString('th-TH')
    }
  });
}

return results;
